package com.yonlab.vision;
import android.content.Context;import android.graphics.Bitmap;import ai.onnxruntime.*;import java.io.*;import java.nio.*;import java.util.*;
import org.opencv.android.*;import org.opencv.core.*;import org.opencv.imgproc.Imgproc;

/** Apache-2.0 Megvii release, raw BGR CHW416 top-left letterbox, raw-head decode. */
final class OneYoloXEngine implements AutoCloseable {
 static final String SHA256="c789161ed43c8269fcd4e67c67eeeb4e80c622da2eb296a20bc6007bd18a0b7d";final String sha256=SHA256;
 private final OrtEnvironment environment;private OrtSession session;private final List<String> labels=new ArrayList<>(),sparse=new ArrayList<>();
 OneYoloXEngine(Context c)throws Exception{byte[] bytes;try(InputStream in=c.getAssets().open("one/models/yolox-nano.onnx")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){if(out.size()+n>8*1024*1024)throw new IOException("YOLOX model size");out.write(b,0,n);}bytes=out.toByteArray();}if(!SHA256.equals(OneOnnx.hash(new ByteArrayInputStream(bytes))))throw new IOException("YOLOX model SHA");OneObjectEngine.read(c,"one/models/coco80-labels.txt",labels);OneObjectEngine.read(c,"models/labelmap.txt",sparse);if(labels.size()!=80)throw new IOException("YOLOX labels");environment=OrtEnvironment.getEnvironment();int threads=OneExecutionSettings.threads(c);try(OrtSession.SessionOptions options=new OrtSession.SessionOptions()){options.setIntraOpNumThreads(threads);options.setInterOpNumThreads(1);session=environment.createSession(bytes,options);}if(session.getNumInputs()!=1||session.getNumOutputs()!=1){session.close();throw new IOException("YOLOX input output contract");}}
 synchronized List<Observations.Detection> analyze(Bitmap image,float threshold)throws Exception{if(session==null||Thread.currentThread().isInterrupted())throw new InterruptedIOException("canceled");float[] values=preprocess(image);String input=session.getInputNames().iterator().next();try(OnnxTensor tensor=OnnxTensor.createTensor(environment,FloatBuffer.wrap(values),new long[]{1,3,416,416});OrtSession.Result output=session.run(Collections.singletonMap(input,tensor))){Object raw=output.get(0).getValue();if(!(raw instanceof float[][][])||((float[][][])raw).length!=1)throw new IOException("YOLOX output rank");List<OneYoloXMath.Box> boxes=OneYoloXMath.decode(((float[][][])raw)[0],image.getWidth(),image.getHeight(),threshold);List<Observations.Detection> found=new ArrayList<>();for(OneYoloXMath.Box box:boxes){String label=labels.get(box.cls);int id=sparse.indexOf(label)-1;if(id<0)throw new IOException("YOLOX COCO sparse label");float left=Math.max(0,Math.min(1,box.left/image.getWidth())),top=Math.max(0,Math.min(1,box.top/image.getHeight())),right=Math.max(0,Math.min(1,box.right/image.getWidth())),bottom=Math.max(0,Math.min(1,box.bottom/image.getHeight()));if(right>left&&bottom>top)found.add(new Observations.Detection(id,label,box.score,left,top,right,bottom));}if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("canceled");return found;}}
 private static float[] preprocess(Bitmap image)throws Exception{if(!OpenCVLoader.initLocal())throw new IOException("YOLOX image engine");Mat rgba=new Mat(),bgr=new Mat(),resized=new Mat(),padded=new Mat(416,416,CvType.CV_8UC3,new Scalar(114,114,114)),region=null;try{Utils.bitmapToMat(image,rgba);Imgproc.cvtColor(rgba,bgr,Imgproc.COLOR_RGBA2BGR);double ratio=Math.min(416d/image.getWidth(),416d/image.getHeight());int w=Math.max(1,(int)(image.getWidth()*ratio)),h=Math.max(1,(int)(image.getHeight()*ratio));Imgproc.resize(bgr,resized,new Size(w,h),0,0,Imgproc.INTER_LINEAR);region=new Mat(padded,new Rect(0,0,w,h));resized.copyTo(region);byte[] pixels=new byte[416*416*3];padded.get(0,0,pixels);float[] out=new float[pixels.length];int area=416*416;for(int i=0;i<area;i++){out[i]=pixels[i*3]&255;out[area+i]=pixels[i*3+1]&255;out[2*area+i]=pixels[i*3+2]&255;}return out;}finally{if(region!=null)region.release();rgba.release();bgr.release();resized.release();padded.release();}}
 public synchronized void close(){OrtSession prior=session;session=null;if(prior!=null)try{prior.close();}catch(OrtException e){throw new IllegalStateException("YOLOX cleanup",e);}}
}
